package egdebuild_test

import (
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/egdaemon/eg/internal/egtest"
	"github.com/egdaemon/eg/internal/testx"
	"github.com/egdaemon/eg/interp/runtime/wasi/ffierrors"
	"github.com/egdaemon/eg/runtime/x/wasi/egdebuild"
	"github.com/stretchr/testify/require"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestBuildContainer(t *testing.T) {
	ctx, done := testx.Context(t)
	defer done()

	require.Error(t, egdebuild.Prepare(egdebuild.Runner(), nil)(ctx, egtest.Op()), ffierrors.ErrNotImplemented)
	s := testx.ReadMD5(os.TempDir(), "Containerfile")
	require.Equal(t, testx.ReadMD5(filepath.Join(".debian", "Containerfile")), s)
}

func TestOptionTimeout(t *testing.T) {
	t.Run("applies without corrupting other config fields", func(t *testing.T) {
		cfg := egdebuild.New("mypkg", "ubuntu", "/src")
		cfg = egdebuild.From(cfg, egdebuild.Option.Timeout(30*time.Minute))
		require.Equal(t, "mypkg", cfg.Name)
		require.Equal(t, "ubuntu", cfg.Distro)
		require.Equal(t, "/src", cfg.SourceDir)
		require.Equal(t, "any", cfg.Architecture)
	})

	t.Run("composes with other options", func(t *testing.T) {
		cfg := egdebuild.New("pkg", "debian", "/src")
		cfg = egdebuild.From(cfg, egdebuild.Option.Timeout(15*time.Minute), egdebuild.Option.Distro("ubuntu"))
		require.Equal(t, "pkg", cfg.Name)
		require.Equal(t, "ubuntu", cfg.Distro)
		require.Equal(t, "/src", cfg.SourceDir)
	})

	t.Run("last timeout option takes precedence", func(t *testing.T) {
		cfg := egdebuild.New("pkg", "debian", "/src")
		cfg = egdebuild.From(cfg, egdebuild.Option.Timeout(time.Hour), egdebuild.Option.Timeout(5*time.Minute))
		require.Equal(t, "pkg", cfg.Name)
		require.Equal(t, "debian", cfg.Distro)
	})
}
